class Solution:
    def numDecodings(self,s: str) -> int:
        if not s or s[0] == '0':
            return 0
        p2=1
        p1=0
        if int(s[0]+s[1]) >= 10 and int(s[0]+s[1]) <= 26:
            p1=2
        for i in range(2,len(s)):
            if int(s[i]+s[i-1]) >= 10 and int(s[i]+s[i-1]) <= 26:
                t=p2
                p2=p1
                p1=t+p1
